-- 만들 것

// 요청을 세는 필터를 자동 구성으로 만든다
// 쓰는 쪽은 의존성만 넣으면 켜진다


-- ① 설정 클래스

package study.lib.counter;

@ConfigurationProperties(prefix = "study.counter")
public class CounterProperties {
    private boolean enabled = true;
    private String header = "X-Count";
    private int threshold = 100;
    // getter, setter 생략
}


-- ② 알맹이

public class CounterFilter extends OncePerRequestFilter {
    private final AtomicLong count = new AtomicLong();
    private final CounterProperties props;

    public CounterFilter(CounterProperties props) { this.props = props; }

    @Override
    protected void doFilterInternal(HttpServletRequest req,
                                    HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        long n = count.incrementAndGet();
        res.setHeader(props.getHeader(), String.valueOf(n));
        if (n > props.getThreshold()) res.setHeader("X-Count-Warn", "넘음");
        chain.doFilter(req, res);
    }
}


-- ③ 자동 구성

@AutoConfiguration
@ConditionalOnWebApplication(type = Type.SERVLET)
@ConditionalOnClass(name = "jakarta.servlet.Filter")
@ConditionalOnProperty(prefix = "study.counter", name = "enabled",
                       havingValue = "true", matchIfMissing = true)
@EnableConfigurationProperties(CounterProperties.class)
public class CounterAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean
    public CounterFilter counterFilter(CounterProperties props) {
        System.out.println("[카운터] 필터 등록 header=" + props.getHeader());
        return new CounterFilter(props);
    }
}


-- ④ 목록에 적는다

$ cat src/main/resources/META-INF/spring/\
org.springframework.boot.autoconfigure.AutoConfiguration.imports
study.lib.counter.CounterAutoConfiguration


