-- 쓰는 쪽이 통째로 바꿀 수 있다

@Configuration
class MyCounterConfig {
    @Bean
    CounterFilter counterFilter(CounterProperties props) {
        System.out.println("[내] 카운터");
        return new CounterFilter(props) {
            @Override protected boolean shouldNotFilter(HttpServletRequest r) {
                return r.getRequestURI().startsWith("/actuator");
            }
        };
    }
}

$ ./gradlew bootRun 2>&1 | grep -E '\[내\]|\[카운터\]'
