-- 조건을 안쪽으로 감싼다

@AutoConfiguration
@EnableConfigurationProperties(CounterProperties.class)
public class CounterAutoConfiguration {

    @Configuration(proxyBeanMethods = false)
    @ConditionalOnClass(name = "io.micrometer.core.instrument.MeterRegistry")
    static class WithMetrics {
        @Bean @ConditionalOnMissingBean
        CounterFilter counterFilter(CounterProperties p, MeterRegistry reg) {
            System.out.println("[카운터] 미터 붙임");
            return new MeteredCounterFilter(p, reg);
        }
    }

    @Configuration(proxyBeanMethods = false)
    @ConditionalOnMissingClass("io.micrometer.core.instrument.MeterRegistry")
    static class WithoutMetrics {
        @Bean @ConditionalOnMissingBean
        CounterFilter counterFilter(CounterProperties p) {
            System.out.println("[카운터] 그냥");
            return new CounterFilter(p);
        }
    }
}

$ ./gradlew bootRun 2>&1 | grep '\[카운터\]'
[카운터] 그냥

